"use client";

import { useCallback, useState } from "react";
import {
  ReactFlowProvider,
  useNodesState,
  useEdgesState,
  addEdge,
  Connection,
  Edge,
} from "reactflow";

import { validateFlowsheetModel } from "@/utils/validateFlowsheetModel";
import { buildFlowsheetModel } from "@/utils/buildFlowsheetModel";
import type { SimulationResult } from "@/types/simulation";

import { BlockLibraryPanel } from "@/components/BlockLibraryPanel";
import { FlowsheetCanvas } from "@/components/FlowsheetCanvas";

import type { MetalType, FlowsheetNode } from "@/types/units";
import { createNodeFromUnit } from "@/utils/createNode";
import { ResultsPanel } from "@/components/ResultsPanel";

function FlowsheetToolInner() {
  const [simulationResult, setSimulationResult] =
    useState<SimulationResult | null>(null);
  const [isSimulating, setIsSimulating] = useState(false);

  const [selectedMetal, setSelectedMetal] = useState<MetalType>("Cu");

  // ✅ state نودها و Edgeها
  const [nodes, setNodes, onNodesChange] = useNodesState<FlowsheetNode>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([]);

  // ✅ فقط برای انتخاب (اگر بعداً لازم شد)
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);

  // ✅ state خوراک (Feed)
  const [feed, setFeed] = useState<{ throughput: number; grade: number }>({
    throughput: 100,
    grade: 1.0,
  });

  // ✅ state برای پاپ‌آپ ویرایش
  const [editNode, setEditNode] = useState<FlowsheetNode | null>(null);
  const [editRecovery, setEditRecovery] = useState<string>("1");
  const [editSplit, setEditSplit] = useState<string>("1");

  // اتصال نودها
  const onConnect = useCallback(
    (connection: Connection) => {
      setEdges((eds) => addEdge({ ...connection, animated: true }, eds));
    },
    [setEdges]
  );

  // برای Drag & Drop
  const onDragOver = useCallback((event: React.DragEvent) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
  }, []);

  const onDrop = useCallback(
    (event: React.DragEvent) => {
      event.preventDefault();
      const raw = event.dataTransfer.getData("application/json");
      if (!raw) return;

      let payload: { type: string; parameters?: any } | null = null;
      try {
        payload = JSON.parse(raw);
      } catch {
        return;
      }

      const unitId = payload.type;
      const bounds = (event.target as HTMLDivElement).getBoundingClientRect();

      const position = {
        x: event.clientX - bounds.left,
        y: event.clientY - bounds.top,
      };

      const newNode = createNodeFromUnit(unitId, position);
      if (!newNode) return;

      setNodes((nds) => nds.concat(newNode));
    },
    [setNodes]
  );

  const handleNodeClick = useCallback((node: FlowsheetNode) => {
    setSelectedNodeId(node.id);
  }, []);

  // 🔹 دابل‌کلیک روی نود → باز شدن پاپ‌آپ
  const handleNodeDoubleClick = useCallback((node: FlowsheetNode) => {
    const params =
      (node.data as any)?.parameters ?? ({ recovery: 1, split_ratio: 1 } as {
        recovery: number;
        split_ratio: number;
      });

    setEditNode(node);
    setEditRecovery(String(params.recovery));
    setEditSplit(String(params.split_ratio));
  }, []);

  const closeEditDialog = useCallback(() => {
    setEditNode(null);
  }, []);

  const handleSaveEditDialog = useCallback(() => {
    if (!editNode) return;

    let rec = parseFloat(editRecovery);
    let split = parseFloat(editSplit);

    if (Number.isNaN(rec)) rec = 1;
    if (Number.isNaN(split)) split = 1;

    // محدود کردن بین 0 و 1
    rec = Math.min(Math.max(rec, 0), 1);
    split = Math.min(Math.max(split, 0), 1);

    const nodeId = editNode.id;

    setNodes((nds) =>
      nds.map((node) =>
        node.id === nodeId
          ? {
              ...node,
              data: {
                ...node.data,
                parameters: {
                  recovery: rec,
                  split_ratio: split,
                },
              },
            }
          : node
      )
    );

    setEditNode(null);
  }, [editNode, editRecovery, editSplit, setNodes]);

  // ✅ اجرای Simulation (ارتباط با Backend)
  const handleRunSimulation = async () => {
    const model = buildFlowsheetModel({
      metal: selectedMetal,
      feed,
      nodes,
      edges,
    });

    console.log("FlowsheetModel to send:", model);

    // 🔍 Validation در فرانت‌اند
    const errors = validateFlowsheetModel(model);
    if (errors.length > 0) {
      setSimulationResult({
        streams: [],
        overall_recovery: 0,
        messages: errors,
      });
      return;
    }

    setIsSimulating(true);

    try {
      const response = await fetch("http://127.0.0.1:8000/simulate", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(model),
      });

      if (!response.ok) {
        const text = await response.text();
        console.error("Simulation API error:", response.status, text);
        setSimulationResult({
          streams: [],
          overall_recovery: 0,
          messages: [
            `Simulation API error: ${response.status}`,
            "Check if the FastAPI server is running on port 8000.",
          ],
        });
      } else {
        const data = (await response.json()) as SimulationResult;
        console.log("SimulationResult from backend:", data);
        setSimulationResult(data);
      }
    } catch (err: any) {
      console.error("Simulation request failed:", err);
      setSimulationResult({
        streams: [],
        overall_recovery: 0,
        messages: [
          "Could not connect to the simulation server.",
          "Make sure FastAPI is running on http://127.0.0.1:8000.",
        ],
      });
    } finally {
      setIsSimulating(false);
    }
  };

  return (
    <main className="min-h-screen flex flex-col">
      {/* ✅ Header بالا */}
      <header className="flex items-center justify-between px-6 py-4 border-b bg-white">
        <div className="flex flex-col">
          <span className="text-xs tracking-wide text-slate-500">
            EDUCATIONAL FLOWSHEET SIMULATOR
          </span>
          <h1 className="text-2xl font-semibold">
            Flowsheet Tool{" "}
            <span className="text-sm text-slate-500">(Copper / Zinc)</span>
          </h1>
        </div>

        <div className="flex items-center gap-2 text-sm">
          <span className="text-slate-500">Metal:</span>
          <button
            onClick={() => setSelectedMetal("Cu")}
            className={`px-3 py-1 rounded-full border text-xs ${
              selectedMetal === "Cu"
                ? "bg-blue-600 text-white border-blue-600"
                : "bg-white text-slate-700 hover:bg-slate-100"
            }`}
          >
            Cu
          </button>
          <button
            onClick={() => setSelectedMetal("Zn")}
            className={`px-3 py-1 rounded-full border text-xs ${
              selectedMetal === "Zn"
                ? "bg-blue-600 text-white border-blue-600"
                : "bg-white text-slate-700 hover:bg-slate-100"
            }`}
          >
            Zn
          </button>
        </div>
      </header>

      {/* ✅ بدنه اصلی: Library + Canvas */}
      <div className="flex flex-1">
        {/* Block Library */}
        <BlockLibraryPanel selectedMetal={selectedMetal} />

        {/* Canvas */}
        <section className="flex-1 bg-slate-50">
          <FlowsheetCanvas
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            onDrop={onDrop}
            onDragOver={onDragOver}
            onNodeClick={handleNodeClick}
            onNodeDoubleClick={handleNodeDoubleClick}
          />
        </section>
      </div>

      {/* 🔻 نوار پایین: Feed + Run Simulation + Results */}
      <footer className="border-t bg-white">
        <div className="px-4 py-3 border-b flex items-center justify-between gap-4 text-sm">
          <div className="flex items-center gap-4">
            <div>
              <div className="text-xs text-slate-500">Feed throughput (t/h)</div>
              <input
                type="number"
                className="border rounded px-2 py-1 text-xs w-24"
                value={feed.throughput}
                onChange={(e) =>
                  setFeed((f) => ({
                    ...f,
                    throughput: parseFloat(e.target.value) || 0,
                  }))
                }
              />
            </div>
            <div>
              <div className="text-xs text-slate-500">Feed grade (%)</div>
              <input
                type="number"
                className="border rounded px-2 py-1 text-xs w-24"
                value={feed.grade}
                onChange={(e) =>
                  setFeed((f) => ({
                    ...f,
                    grade: parseFloat(e.target.value) || 0,
                  }))
                }
              />
            </div>
          </div>

          <button
            onClick={handleRunSimulation}
            disabled={isSimulating}
            className={`px-3 py-1.5 rounded-md text-xs font-medium ${
              isSimulating
                ? "bg-slate-300 text-slate-600 cursor-not-allowed"
                : "bg-emerald-600 text-white hover:bg-emerald-700"
            }`}
          >
            {isSimulating ? "Simulating..." : "Run Simulation"}
          </button>
        </div>

        <ResultsPanel
          result={simulationResult}
          isSimulating={isSimulating}
          onRunSimulation={handleRunSimulation}
        />
      </footer>

      {/* 🔹 Popup ویرایش واحد – وسط صفحه + پس‌زمینه تیره */}
      {editNode && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-lg w-full max-w-sm p-4">
            <h2 className="text-sm font-semibold mb-3">Edit Unit Parameters</h2>
            <div className="text-xs text-slate-500 mb-2">
              {(editNode.data as any)?.label}
            </div>

            <div className="space-y-3 mb-4">
              <div>
                <label className="block text-xs text-slate-600 mb-1">
                  Recovery (0–1, fraction)
                </label>
                <input
                  type="number"
                  step="0.01"
                  min={0}
                  max={1}
                  value={editRecovery}
                  onChange={(e) => setEditRecovery(e.target.value)}
                  className="w-full border rounded px-2 py-1 text-xs"
                />
              </div>
              <div>
                <label className="block text-xs text-slate-600 mb-1">
                  Split ratio to concentrate (0–1)
                </label>
                <input
                  type="number"
                  step="0.01"
                  min={0}
                  max={1}
                  value={editSplit}
                  onChange={(e) => setEditSplit(e.target.value)}
                  className="w-full border rounded px-2 py-1 text-xs"
                />
              </div>
            </div>

            <div className="flex justify-end gap-2 text-xs">
              <button
                onClick={closeEditDialog}
                className="px-3 py-1 rounded border border-slate-300 text-slate-700 hover:bg-slate-100"
              >
                Cancel
              </button>
              <button
                onClick={handleSaveEditDialog}
                className="px-3 py-1 rounded bg-emerald-600 text-white hover:bg-emerald-700"
              >
                Save
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

export default function FlowsheetToolPage() {
  return (
    <ReactFlowProvider>
      <FlowsheetToolInner />
    </ReactFlowProvider>
  );
}