// src/components/FlowsheetCanvas.tsx
"use client";

import {
  Background,
  Controls,
  MiniMap,
  ReactFlow,
  Handle,
  Position,
  Connection,
  Edge,
  NodeTypes,
} from "reactflow";

import type { FlowsheetNode } from "@/types/units";

interface FlowsheetCanvasProps {
  nodes: FlowsheetNode[];
  edges: Edge[];
  onNodesChange: (changes: any) => void;
  onEdgesChange: (changes: any) => void;
  onConnect: (connection: Connection) => void;
  onDrop: (event: React.DragEvent) => void;
  onDragOver: (event: React.DragEvent) => void;
  onNodeClick?: (node: FlowsheetNode) => void;
  onNodeDoubleClick?: (node: FlowsheetNode) => void;
}

// 👇 نوع data داخل نود (همون چیزی که در createNodeFromUnit ست می‌کنی)
type UnitNodeData = {
  label: string;
  metal: string;
  icon?: string;
  parameters: {
    recovery: number;
    split_ratio: number;
  };
};

// 👇 کامپوننت نود سفارشی (فقط یک کادر + آیکون + Rec/Split + دو Handle)
function UnitNode({ data }: { data: UnitNodeData }) {
  const { label, icon, metal, parameters } = data;

  return (
    <div
      className="unit-node"
      style={{
        minWidth: 220,
        padding: "8px 12px",
        borderRadius: 12,
        border: "1px solid #cbd5e1",
        background: "#ffffff",
        display: "flex",
        alignItems: "center",
        gap: 8,
        boxShadow: "0 1px 2px rgba(15,23,42,0.08)",
      }}
    >
      {/* Handle بالا (ورودی) */}
      <Handle
        type="target"
        position={Position.Top}
        style={{ background: "#0f172a", width: 8, height: 8 }}
      />

      {/* آیکون */}
      <div
        style={{
          width: 32,
          height: 32,
          borderRadius: 8,
          overflow: "hidden",
          background: "#e2e8f0",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexShrink: 0,
        }}
      >
        {icon ? (
          <img
            src={`/icons/${icon}.png`}
            alt={label}
            style={{
              maxWidth: "100%",
              maxHeight: "100%",
              objectFit: "contain",
            }}
          />
        ) : (
          <span
            style={{
              fontSize: 10,
              fontWeight: 600,
              color: "#0f172a",
            }}
          >
            {metal}
          </span>
        )}
      </div>

      {/* متن */}
      <div style={{ display: "flex", flexDirection: "column", fontSize: 12 }}>
        <span style={{ fontWeight: 600, marginBottom: 2 }}>{label}</span>
        <span style={{ fontSize: 11, color: "#64748b" }}>
          Rec: {parameters.recovery} • Split: {parameters.split_ratio}
        </span>
      </div>

      {/* Handle پایین (خروجی) */}
      <Handle
        type="source"
        position={Position.Bottom}
        style={{ background: "#0f172a", width: 8, height: 8 }}
      />
    </div>
  );
}

const nodeTypes: NodeTypes = {
  unit: UnitNode,
};

export function FlowsheetCanvas({
  nodes,
  edges,
  onNodesChange,
  onEdgesChange,
  onConnect,
  onDrop,
  onDragOver,
  onNodeClick,
  onNodeDoubleClick,
}: FlowsheetCanvasProps) {
  return (
    <div
      style={{ width: "100%", height: "100%" }}
      onDrop={onDrop}
      onDragOver={onDragOver}
    >
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        nodeTypes={nodeTypes}
        fitView
        onNodeClick={(_, node) =>
          onNodeClick && onNodeClick(node as FlowsheetNode)
        }
        onNodeDoubleClick={(_, node) =>
          onNodeDoubleClick && onNodeDoubleClick(node as FlowsheetNode)
        }
      >
        <Background gap={16} size={1} color="#e2e8f0" />
        <Controls />
        <MiniMap />
      </ReactFlow>
    </div>
  );
}